export default function CreatorsEconomy() {
  const { slug } = useParams();
  const activeStory = creatorStories.find((story) => story.slug === slug);

  if (activeStory) {
    return <CreatorsEconomyArticle story={activeStory} />;
  }

  return <CreatorsEconomyHub />;
}
